<?php
namespace App\Models\Concerns; use App\Support\BranchContext; use Illuminate\Database\Eloquent\Builder;
trait BelongsToBranch { public static function bootBelongsToBranch():void { static::addGlobalScope('branch',function(Builder $builder){if(app()->bound(BranchContext::class)&&($id=app(BranchContext::class)->id()))$builder->where($builder->qualifyColumn('branch_id'),$id);});static::creating(function($model){if($model->branch_id)return;$context=app()->bound(BranchContext::class)?app(BranchContext::class)->branch():null;if($context&&((int)$context->company_id===(int)$model->company_id)){$model->branch_id=$context->id;return;}$model->branch_id=\App\Models\Branch::where('company_id',$model->company_id)->where('is_main',true)->value('id');}); } public function branch(){return $this->belongsTo(\App\Models\Branch::class);} }
